export function installEditing({canvas,scene,getDocument,getSelection,open,changed,status,isLoading,switchWorkspace,hasUnsaved,aimSpotlight}){
 let workbench=null;const $=id=>document.getElementById(id),panel=document.createElement('section');panel.id='editing-tools';
 panel.innerHTML=`<h2>Build</h2><details><summary>Locks & repairs</summary><label>Lock difficulty (0 = unlocked)<input id="lock-difficulty" type="number" min="0" max="100" value="50"></label><button id="apply-door-lock">Apply to selected closed door</button><label>Fixture condition<input id="fixture-condition" type="number" min="0" max="100" value="0"></label><button id="apply-fixture-condition">Apply to selected light</button><p class="muted">Select a door boundary or electrical fixture. Damaged fixtures stay off until repaired to 100%. Locks stay with saved maps and blocks.</p></details><label>Tool<select id="edit-tool"></select></label><p class="muted">Cliff climb · 8 AP: paint upper landing floors, then click the lower tile edge toward the landing. Horse/rifle animation needs a straight ledge three tiles wide with clear approaches and landings.</p><div id="foliage-brush" hidden><label>Paint area<select id="foliage-shape"><option value="round">Round brush - click and drag</option><option value="square">Square brush - click and drag</option><option value="rectangle">Drag rectangle</option></select></label><label id="foliage-width">Brush width (tiles)<input id="foliage-size" type="number" min="1" max="63" value="17"></label></div><div id="foliage-options" hidden><label><span id="foliage-density-label">Undergrowth density</span> · <output id="foliage-density-value">65%</output><input id="foliage-density" type="range" min="1" max="100" step="1" value="65"></label><label>Preset<select id="foliage-preset">${Object.entries(FOLIAGE_PRESETS).filter(([id])=>id!=='bog-v1').map(([id,p])=>`<option value="${id}" ${id==='thicket-v1'?'selected':''}>${p.label}</option>`).join('')}</select></label><p class="muted" id="foliage-rules"></p><label>Movement<select id="foliage-passability"><option value="blocked">Impassable</option><option value="passable">Passable</option></select></label><p class="muted">Drag to paint broad swaths. Plants automatically match the local environment. Paint Jungle floor, Temperate meadow, Snow, Dry grassland or Wetland grass with Tiles to override it. Passable creates light woods with spaced trees and grass; routes go around the trunks. Density adds growth while keeping wide gaps. Dense presets keep a full sight screen even at low decorative density. Wetlands keep bog water and unsafe land patches beneath the dense screen. Works on outdoor layers 1–6. Water, structures, objects and access points are protected. Release to place; Escape cancels.</p></div><p id="foliage-help" class="muted" hidden>Erase foliage with the same area brush. The original ground stays intact. Clearing older foliage tiles restores grass.</p><div id="land-options" hidden><label>Land height<select id="land-height"><option value="0">Ground · lower / remove plateau</option><option value="1" selected>First plateau · altitude 2</option><option value="2">Plateau · layer 3</option><option value="3">Plateau · layer 4</option><option value="4">High plateau · layer 5</option><option value="5">High terrain · layer 6</option></select></label><label>Brush shape<select id="land-shape"><option value="round">Round</option><option value="square">Square</option></select></label><label>Brush width (tiles)<input id="land-size" type="number" min="1" max="63" value="9"></label><p class="muted">All levels stay visible. The level buttons and Land height select the same editing layer. Click and drag to paint a plateau. Release to build the top and closed cliff walls; Escape cancels. Overlapping strokes join automatically. Ground lowers painted land. Add climb points with Cliffs → Cliff climb, or drag Ramps along a straight wall at its lower altitude. Existing access routes and objects are protected.</p></div><div id="cliff-options" hidden><label>Cliff form<select id="cliff-kind"><option value="cliff-ledge">Ledge</option><option value="cliff-crag">Crag</option></select></label><label>Cliff shape<select id="cliff-mask"><option value="15">Full tile</option><option value="3">North edge</option><option value="6">East edge</option><option value="12">South edge</option><option value="9">West edge</option><option value="1">Northwest corner</option><option value="2">Northeast corner</option><option value="4">Southeast corner</option><option value="8">Southwest corner</option><option value="14">Cut northwest corner</option><option value="13">Cut northeast corner</option><option value="11">Cut southeast corner</option><option value="7">Cut southwest corner</option><option value="5">Northwest / southeast</option><option value="10">Northeast / southwest</option></select></label><label>Contour<select id="cliff-variant"><option value="0">A</option><option value="1">B</option><option value="2">C</option></select></label><label>Surface<select id="cliff-sand"><option value="0">Grass</option><option value="0.5">Grass / sand</option><option value="1">Sand</option></select></label><p class="muted">Drag to paint connected cliff tiles. Neighboring edges must meet. Ground movement is blocked. Use the separate Cliff climb tool to mark an 8 AP climb.</p></div><div id="ramp-options" hidden><label>Placement<select id="ramp-placement"><option value="wall">Drag along cliff wall</option><option value="manual">Place individual ramp</option></select></label><label>Surface<select id="ramp-surface"><option value="grass">Grass</option><option value="sand">Sand</option><option value="road">Asphalt road</option><option value="concrete">Concrete</option><option value="wood">Wooden ramp · side rails · 1 × 3</option><option value="woodsupport">Dark wood ramp · trellis underneath · 1 × 3</option><option value="woodgold">Golden wood ramp · trellis underneath · 1 × 3</option></select></label><label>Uphill direction<select id="ramp-direction"><option>north</option><option>east</option><option>south</option><option>west</option></select></label><p id="ramp-help" class="muted">Click the exposed face of a straight, full ledge wall at its lower altitude, then drag along the wall to set the ramp width. Wooden ramps extend three tiles; other ramps extend four tiles out from the wall; missing upper landing floors are added. Direction follows the wall. Individual placement uses the direction selector and R to turn.</p></div><div id="bank-options" hidden><label>Bank surface<select id="bank-surface"><option>dirt</option><option>grass</option><option>sand</option></select></label><label>Ramp uphill direction<select id="bank-direction"><option>north</option><option>east</option><option>south</option><option>west</option></select></label><label>Side looking uphill<select id="bank-side"><option>left</option><option>right</option></select></label><label>Segment<select id="bank-step"><option value="0">1 · Foot</option><option value="1">2 · Lower middle</option><option value="2">3 · Upper middle</option><option value="3">4 · Crest</option></select></label><p class="muted">An inaccessible joining tile. Select a placed ramp and use Add banks to selected ramp to place both complete sides.</p></div><label>Terrain<select id="ground-kind"></select></label><label>Object variant<select id="prop-kind"></select></label><label id="scenery-orientation-label" hidden>Scenery facing<select id="scenery-rotation"><option value="0">0°</option><option value="90">90°</option><option value="180">180°</option><option value="270">270°</option></select></label><div id="machine-options" hidden><p class="muted" id="machine-dimensions"></p><p class="muted">R cycles four orientations. The arrow marks the working face; green outline tiles show free approach space without reserving it. Machines provide physical cover: real openings remain clear. The mill and press need an open ceiling. Failed placements leave the map intact.</p></div><div id="helicopter-options" hidden><p class="muted">The helicopter reserves 12 x 10 tiles for its body, rotor and debris. Clear space under the rotor remains walkable. Residual smoke is harmless. Place the survivors / smoke version in the tutorial clearing, select it, then set the squad start below.</p><button id="set-helicopter-start">Set squad start beside crash</button><p class="muted">Places all four mercs outside the cabin exit, facing southwest. Their identities and equipment stay intact. Undo restores the previous starts.</p></div><div id="furnishing-help" hidden><p class="muted">Chairs and consoles occupy one tile and provide low cover. Sitting, computer use and telephone interactions await gameplay integration.</p></div><div id="site-options"><label><input id="site-sabotage" type="checkbox"> Allow sabotage action</label><button id="apply-site-sabotage">Apply to selected strategic site</button><p class="muted">Radio towers, radar towers and SAM sites reserve 8 × 8 ground tiles, with open paths through their structures. Fire and explosions leave a wreck. Enable scripted sabotage without demolition charges on ordinary sites: a merc beside the controls can destroy one for 6 AP in combat or 1 minute in exploration. Plateau tutorial mission roles instead require demolition explosives. The wreck stays in saved games. Strategic radar, air defence and radio effects await campaign integration.</p></div><p class="muted">Ramps rise one level. Wooden ramps span 3 tiles with crosswise planks and either side rails or trellis supports underneath; other ramps span 4 tiles. Keep the footprint and lower approach clear. A wall drag creates the whole width as one undoable edit.</p><label>Light schedule<select id="light-mode"><option value="auto">Automatic · lamps at night, fires always</option><option value="on">Always on</option><option value="off">Off / extinguished</option></select></label><button id="apply-light-mode">Apply to selected light</button><label>Ramp bank surface<select id="ramp-bank-surface"><option value="dirt">Dirt</option><option value="grass">Grass</option><option value="sand">Sand</option></select></label><button id="add-ramp-banks">Add banks to selected ramp</button><button id="add-lookout">Add lookout to selected tower</button><p class="muted">Lookouts use the species, weapon and outfit below. Mercs can climb at the gold entrance ring in playtest.</p><button id="aim-spotlight">Set spotlight aim points</button><p class="muted">Right-click a spotlight or searchlight tower and choose Set aim points, or select it and use this button. Click up to 3 tiles to add red flags; click a flag again for 15 seconds of wait. Done or Escape finishes. Every change supports Undo and Redo.</p><p class="muted">Light reaches 5 tiles at full strength, then halves every 5 tiles. Wall fixtures mount at the north edge; rotated fixtures mount at the east edge.</p><label>Boundary<select id="edge-kind"></select></label><div class="row"><label>Room width<input id="room-width" type="number" min="2" max="24" value="6"></label><label>Depth<input id="room-height" type="number" min="2" max="24" value="5"></label></div><label class="check"><input type="checkbox" id="rotated">Rotate placement 90°</label><details><summary>Character placement</summary><label>Species<select id="unit-species"></select></label><label>Weapon<select id="unit-weapon"></select></label><label>Outfit<select id="unit-outfit"><option value="normal">Normal</option><option value="red-hats">Red Hats</option><option value="blue-hawaiian">Town guide · donkey Hawaiian shirt</option></select></label><label>Facing (degrees)<input id="unit-heading" type="number" min="0" max="359" value="225"></label><label>Squad slot<select id="unit-slot"><option value="0">1</option><option value="1">2</option><option value="2">3</option><option value="3">4</option></select></label></details><div class="row"><button id="undo">Undo</button><button id="redo">Redo</button></div><div class="row"><button id="rotate-selected">Rotate selected</button><button id="delete-selected">Delete selected</button></div><button id="use-selected">Copy selected settings</button><p class="muted">Select / pan: drag camera. Build tools: drag a stroke, release to place. Right-drag to pan. Escape cancels. R rotates the preview.</p>`;
 document.querySelector('.tools').insertBefore(panel,document.querySelector('.tools h2'));
 const save=document.createElement('section');save.innerHTML=`<h2>Design</h2><label>Name<input id="design-name" maxlength="60"></label><div class="row"><button id="new-map">New map</button><button id="rename-map">Rename</button></div><div class="row"><button id="save-map">Save</button><button id="save-copy">Save copy</button></div><label>Saved designs<select id="saved-designs"></select></label><button id="load-map">Load selected</button><div class="row"><button id="validate-map">Validate</button><button id="playtest">Playtest ↗</button></div><label>Start time<input id="start-time" type="time" value="08:00"></label><button id="apply-start-time">Apply start time</button><p class="muted">Exploration: 1 game minute per 3 real seconds. Combat: 1 minute per completed round.</p><label>Preview daylight<input id="light-preview" type="range" min="0" max="1439" step="1" value="480"></label><output id="light-preview-label"></output><button id="light-preview-reset">Use map start time</button><p class="muted">Preview only. East is +X; west is −X. Apply start time above to change when play begins.</p><p id="validation" role="status"></p>`;document.querySelector('.properties').prepend(save);
 const add=(id,items)=>{for(const [value,label]of items)$(id).add(new Option(label,value));};
 add('edit-tool',[['inspect','Select / pan'],['land','Paint land & automatic cliffs'],['texture','Paint terrain'],['floor','Paint floor'],['cliff','Cliff walls / diagonal tiles'],['ramp','Ramps · wood, cliff and road'],['ramp-bank','Cliff / ramp joining bank'],['erase-cliff','Erase cliffs'],['water','Water'],['bridge','Bridge'],['foliage-cover','Foliage cover'],['clear-foliage','Clear foliage'],['wall','Wall / fence'],['break-wall','Break wall'],['break-floor','Break floor'],['door','Door opening'],['room','Custom room'],['prefab','Preset structure'],['prop','Objects'],['roof-tile','Roof tiles'],['guard','Guard'],['npc','NPCs'],['squad','Squad start'],['exit','Travel marker'],['stairs','Stairs'],['ladder','Ladder'],['ladder-rusty','Rusty ladder · 1% critical failure'],['roof','Roof climb'],['cliff-climb','Cliff climb · 8 AP'],['erase-prop','Erase prop'],['remove-guard','Erase guard'],['erase-edge','Erase boundary'],['erase-tile','Erase terrain'],['erase-stairs','Erase stairs'],['erase-roof','Erase climb']]);
 for(const [id,items]of [['ground-kind',GROUNDS],['prop-kind',Object.keys(PROPS).filter(kind=>!isCliff({kind}))],['edge-kind',Object.keys(EDGES)],['unit-species',SPECIES],['unit-weapon',WEAPON_IDS]])add(id,items.map(x=>[x,id==='ground-kind'?(BIOME_TERRAIN_NAMES[x]||(x==='ground-wood-planks'?'Wooden planks':roadLabel(x))):id==='prop-kind'?(HEDGE_PROPS[x]?.name||SCENERY_PROPS[x]?.name||SITE_PROPS[x]?.name||(x==='barrel-explosive'?'Explosive barrel · red / flammable':roofLabel(x))):x==='wall-wood-trellis'?'Wooden bridge trellis':x==='wall-wood-trellis-arch'?'Wooden trellis archway · passable':x]));
 $('foliage-options').insertAdjacentHTML('afterbegin','<label>Paint mode<select id="foliage-mode"><option value="paint">Paint foliage</option><option value="tree-cover">Change tree cover only</option></select></label><label id="tree-cover-label">Tree cover<select id="foliage-tree-cover"><option value="multiple" disabled>Multiple values — choose a mix</option>'+Object.entries(TREE_COVER).map(([id,p])=>'<option value="'+id+'">'+p.label+'</option>').join('')+'</select></label><label>Inspect vegetation<select id="foliage-inspect"><option value="both">Trees and brush</option><option value="trees">Trees only</option><option value="brush">Brush only</option></select></label><p id="foliage-preview-help" class="muted">Preview: green rings add trees, gold retains them, red removes them. Protected tiles are outlined. Shift-drag with Select to inspect an area.</p>');
 $('foliage-tree-cover').value='brush-v1';
 const inspectionNotice=document.createElement('div');inspectionNotice.id='foliage-inspection-notice';inspectionNotice.textContent='Visual inspection only; obstruction is unchanged';inspectionNotice.hidden=true;inspectionNotice.style.cssText='position:fixed;left:50%;top:65px;transform:translateX(-50%);background:#e8d6a6;color:#352819;padding:8px 12px;z-index:30;pointer-events:none';document.body.append(inspectionNotice);
 $('foliage-inspect').onchange=()=>{scene.biomes.inspection=$('foliage-inspect').value;inspectionNotice.hidden=scene.biomes.inspection==='both';scene.changed();};
 const foliagePreview=new FoliagePreviewClient(r=>{scene.preview(r);status(r.ok?r.cells.length+' tiles · Tree preview: green adds, gold keeps, red removes · Release to place':r.error);});
 window.addEventListener('pagehide',()=>foliagePreview.stop(),{once:true});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)foliagePreview.stop();});
 $('unit-species').value='pig-foreman';$('unit-weapon').value='pistol';
 let stroke=null,strokePath=[],lastPreview='',recordId=null,busy=false,request=0,pending=null,hoverPoint=null;
 const options=()=>({foliageMode:$('foliage-mode').value,foliageTreeCover:$('foliage-tree-cover').value,foliagePreset:$('foliage-preset').value,foliageDensity:+$('foliage-density').value,foliageBlocked:$('foliage-passability').value==='blocked',foliageSize:+$('foliage-size').value,foliageShape:$('foliage-shape').value,sabotage:$('site-sabotage').checked,landHeight:+$('land-height').value,landSize:+$('land-size').value,landShape:$('land-shape').value,rampSurface:$('ramp-surface').value,preset:document.getElementById('structure-preset')?.value||'shed',cliffKind:$('cliff-kind').value,cliffMask:+$('cliff-mask').value,cliffVariant:+$('cliff-variant').value,cliffSand:+$('cliff-sand').value,groundKind:$('ground-kind').value,propKind:$('edit-tool').value==='ramp'?`ramp-${$('ramp-surface').value}-${$('ramp-direction').value}`:$('edit-tool').value==='ramp-bank'?`rampbank-${$('bank-surface').value}-${$('bank-direction').value}-${$('bank-side').value}-${$('bank-step').value}`:$('prop-kind').value,lightMode:$('light-mode').value,edgeKind:$('edge-kind').value,width:+$('room-width').value,height:+$('room-height').value,rotation:isScenery({kind:$('prop-kind').value})?+$('scenery-rotation').value:undefined,rotated:isScenery({kind:$('prop-kind').value})?+$('scenery-rotation').value%180===90:['ramp','ramp-bank'].includes($('edit-tool').value)?false:$('rotated').checked,species:$('unit-species').value,weapon:$('unit-weapon').value,outfit:$('unit-outfit').value,heading:+$('unit-heading').value,slot:+$('unit-slot').value});
 const point=e=>{const b=canvas.getBoundingClientRect(),p=($('edit-tool').value==='ramp'&&$('ramp-placement').value==='wall'?scene.pickCliff(e.clientX-b.left,e.clientY-b.top,b.width,b.height):null)||scene.pick(e.clientX-b.left,e.clientY-b.top,b.width,b.height);return p&&brushPoint(p);};
 const rememberPoint=p=>{if(!stroke||!p||!['land','foliage-cover','clear-foliage'].includes($('edit-tool').value))return;const last=strokePath.at(-1);if(!last||p.x!==last.x||p.y!==last.y)strokePath.push(p);};
 const command=p=>({path:['land','foliage-cover','clear-foliage'].includes($('edit-tool').value)&&stroke?[...strokePath]:undefined,tool:$('edit-tool').value==='ramp'?($('ramp-placement').value==='wall'?'ramp':'prop'):$('edit-tool').value==='ramp-bank'?'prop':$('edit-tool').value,start:stroke||p,end:['foliage-cover','clear-foliage','wall','door','erase-edge','break-wall'].includes($('edit-tool').value)||$('edit-tool').value==='ramp'&&$('ramp-placement').value==='wall'?p:document.getElementById('stroke-mode')?.value==='single'?(stroke||p):p,options:options()});
 function preview(p){if(!p)return;const c=command(p),key=JSON.stringify(c);if(key===lastPreview)return;lastPreview=key;if(['foliage-cover','clear-foliage'].includes(c.tool)){foliagePreview.request(getDocument(),c);return;}const r=getDocument().preview(c);if(c.tool==='prop'&&isScenery({kind:c.options.propKind}))r.sceneryPreview={...c.start,kind:c.options.propKind,...sceneryOrientation(c.options)};scene.preview(r);status(r.ok?(r.cells.length+' tiles · Release to place · Escape cancels'):r.error);}
 $('land-height').addEventListener('change',()=>{$('floor').value=$('land-height').value;$('floor').dispatchEvent(new Event('change'));});
 $('floor').addEventListener('change',()=>{cancel();$('land-height').value=Math.min(MAP_LEVELS-1,+$('floor').value);});
 const cancel=()=>{foliagePreview.stop();stroke=null;strokePath=[];pending=null;lastPreview='';scene.preview(null);scene.select(getSelection());};
 async function apply(c){if(busy||isLoading())return {ok:false,error:'Wait for the scene to finish loading.'};const result=getDocument().apply(c);if(result.ok){busy=true;cancel();try{await changed();sync();status('Edit applied.');}finally{busy=false;}}else status(result.error);return result;}
 $('aim-spotlight').onclick=()=>{if(busy||isLoading())return;cancel();aimSpotlight(getSelection()?.data);};
 canvas.addEventListener('contextmenu',e=>e.preventDefault());
 canvas.addEventListener('pointerdown',e=>{if(e.button!==0||$('edit-tool').value==='inspect')return;e.stopImmediatePropagation();if(busy||isLoading())return;stroke=point(e);strokePath=[];rememberPoint(stroke);canvas.setPointerCapture(e.pointerId);canvas.focus();lastPreview='';preview(stroke);},true);
 canvas.addEventListener('pointermove',e=>{if($('edit-tool').value==='inspect'||e.buttons===2||busy||isLoading())return;e.stopImmediatePropagation();hoverPoint=point(e);rememberPoint(hoverPoint);pending=hoverPoint;if(!request)request=requestAnimationFrame(()=>{request=0;if(pending)preview(pending);pending=null;});},true);
 canvas.addEventListener('pointerup',e=>{if(e.button!==0||!stroke)return;e.stopImmediatePropagation();const end=point(e);rememberPoint(end);const c=command(end||stroke);cancel();apply(c);},true);
 canvas.addEventListener('pointercancel',cancel,true);canvas.addEventListener('pointerleave',()=>{if(!stroke)cancel();});
 function rampControls(){const wooden=$('ramp-surface').value.startsWith('wood'),wall=$('ramp-placement').value==='wall';$('ramp-direction').closest('label').hidden=wall;$('ramp-help').textContent=wall?'Click the exposed face of a straight cliff wall and drag along it. Direction follows the wall; upper landing floors are added.':wooden?'Place at the lower altitude. The ramp occupies 1 × 3 tiles and rises one level toward the selected direction. Paint an upper landing floor directly beyond the high end. Keep both ends clear. R rotates placement.':'Place at the lower altitude. The ramp occupies 1 × 4 tiles and needs a full cliff ledge with an upper landing floor beyond the high end. R rotates placement.';}
 function controls(){rampControls();const tool=$('edit-tool').value;if(tool==='land'&&$('floor').value==='3'){$('floor').value='2';$('floor').dispatchEvent(new Event('change'));}$('ramp-direction').closest('label').hidden=$('ramp-placement').value==='wall';$('land-options').hidden=tool!=='land';$('cliff-options').hidden=tool!=='cliff';$('ramp-options').hidden=tool!=='ramp';$('bank-options').hidden=tool!=='ramp-bank';$('foliage-brush').hidden=!['foliage-cover','clear-foliage'].includes(tool);$('foliage-width').hidden=$('foliage-shape').value==='rectangle';$('foliage-options').hidden=tool!=='foliage-cover';$('foliage-help').hidden=tool!=='clear-foliage';for(const [id,visible]of [['ground-kind',['texture','land'].includes(tool)],['prop-kind',['prop','roof-tile'].includes(tool)],['edge-kind',tool==='wall'],['rotated',['prop','roof-tile','room'].includes(tool)]])$(id).closest('label').hidden=!visible;$('room-width').closest('.row').hidden=tool!=='room';const detail=$('unit-species').closest('details');detail.hidden=!['guard','npc','squad','inspect'].includes(tool);detail.open=true;workbench?.context();}
 $('scenery-rotation').addEventListener('change',()=>{lastPreview='';if(hoverPoint)preview(hoverPoint);});$('ramp-placement').addEventListener('change',rampControls);$('ramp-surface').addEventListener('change',()=>{if($('ramp-surface').value.startsWith('wood'))$('ramp-placement').value='manual';rampControls();cancel();});
 const foliageRules=()=>{const dense=denseTreePreset($('foliage-preset').value),only=$('foliage-mode').value==='tree-cover';$('tree-cover-label').hidden=!dense&&!only;$('foliage-density-label').textContent=dense?'Undergrowth density':'Woodland density';$('foliage-rules').textContent=FOLIAGE_PRESETS[$('foliage-preset').value].summary+(dense?' Tree cover adds solid trunks independently of undergrowth density.':' Woodland density affects spaced trees and low grass.');for(const id of ['foliage-preset','foliage-density','foliage-passability'])$(id).disabled=only;};
 $('foliage-mode').onchange=()=>{foliageRules();lastPreview='';};
 $('foliage-preset').addEventListener('change',()=>{$('foliage-passability').value=FOLIAGE_PRESETS[$('foliage-preset').value].blocked?'blocked':'passable';foliageRules();lastPreview='';});
 $('foliage-passability').addEventListener('change',()=>{$('foliage-preset').value=$('foliage-passability').value==='blocked'?'thicket-v1':'woodland-v1';foliageRules();lastPreview='';});foliageRules();
 $('foliage-shape').addEventListener('change',controls);$('foliage-density').addEventListener('input',()=>{$('foliage-density-value').value=$('foliage-density').value+'%';lastPreview='';});
 $('edit-tool').onchange=()=>{cancel();controls();};controls();for(const e of panel.querySelectorAll('select,input'))e.addEventListener('change',()=>{lastPreview='';if(stroke)preview(stroke);});
 async function history(direction){if(busy||isLoading())return;cancel();if(getDocument()[direction]()){busy=true;try{await changed();sync();status(direction==='undo'?'Undone.':'Redone.');}finally{busy=false;}}}
 $('undo').onclick=()=>history('undo');$('redo').onclick=()=>history('redo');
 $('delete-selected').onclick=()=>{const s=getSelection();if(!s)return status('Select an object first.');const tool=s.type==='prop'?'erase-prop':s.type==='edge'?'erase-edge':s.type==='unit'&&s.data.id.startsWith('guard')?'remove-guard':s.type==='tile'?'erase-tile':null;if(!tool)return status('Squad starts and travel markers must be repositioned with their placement tools.');apply({tool,start:{x:s.x,y:s.y,z:s.z,edge:s.edge},options:{}});};
 $('rotate-selected').onclick=async()=>{if(busy||isLoading())return;const r=getDocument().rotate(getSelection());if(!r.ok)return status(r.error);busy=true;try{await changed();sync();}finally{busy=false;}};
 $('use-selected').onclick=()=>{const s=getSelection();if(s?.type==='tile'&&s.cells?.some(p=>foliageAt(getDocument().map,p.x,p.y,p.z||0))){const cells=s.cells.map(p=>foliageAt(getDocument().map,p.x,p.y,p.z||0)),first=cells.find(Boolean),p=s.cells[cells.indexOf(first)];$('foliage-preset').value=foliagePreset(getDocument().map,p.x,p.y,p.z||0);$('foliage-density').value=first[0];$('foliage-density-value').value=first[0]+'%';$('foliage-passability').value=first[1]?'blocked':'passable';$('foliage-tree-cover').value=treeCoverSelection(cells);$('edit-tool').value='foliage-cover';foliageRules();}else if(s?.data?.broken){$('edit-tool').value=s.type==='edge'?'break-wall':'break-floor';}else if(s?.type==='prop'&&isCliff(s.data)){$('cliff-kind').value=s.data.kind;$('cliff-mask').value=s.data.cliffMask??15;$('cliff-variant').value=s.data.cliffVariant??0;$('cliff-sand').value=s.data.cliffSand??(s.data.kind==='cliff-crag'?1:0);$('edit-tool').value='cliff';}else if(s?.type==='prop'&&isRamp(s.data)){const [,surface,direction]=s.data.kind.split('-');$('ramp-surface').value=surface;$('ramp-direction').value=direction;$('edit-tool').value='ramp';$('ramp-placement').value='manual';}else if(s?.type==='prop'){/* Populate the destination category before assigning its filtered variant. */$('edit-tool').value=s.data.kind.startsWith('roof-')?'roof-tile':'prop';controls();$('prop-kind').value=s.data.kind;$('site-sabotage').checked=s.data.sabotage===true;$('light-mode').value=s.data.lightMode||'auto';$('rotated').checked=!!s.data.rotated;if(isScenery(s.data))$('scenery-rotation').value=sceneryRotation(s.data);}else if(s?.type==='unit'&&s.data.id.startsWith('guard')){for(const [id,key]of [['unit-species','species'],['unit-weapon','weapon'],['unit-outfit','outfit'],['unit-heading','heading']])$(id).value=s.data[key]??(key==='outfit'?'normal':225);$('edit-tool').value='guard';}else status('Select foliage, an object or a guard.');cancel();controls();};
 async function rotateBoth(){if(busy||isLoading())return;let note='Placement rotated.';const selected=getSelection();if(selected){const r=getDocument().rotate(selected);if(r.ok){await changed();sync();note='Selection and placement rotated.';}else note=r.error;}
 const tool=$('edit-tool').value;if(tool==='land'){note='The land brush has no rotation.';}else if(tool==='ramp'&&$('ramp-placement').value==='wall'){note='Ramp direction follows the cliff wall.';}else if(['ramp','ramp-bank'].includes(tool)){const select=$(tool==='ramp'?'ramp-direction':'bank-direction');select.selectedIndex=(select.selectedIndex+1)%4;}else if(tool==='texture'&&diagonalRoad($('ground-kind').value)){const info=diagonalRoad($('ground-kind').value),next=ROAD_CORNERS[(ROAD_CORNERS.indexOf(info.corner)+1)%4];$('ground-kind').value=$('ground-kind').value.replace('-'+info.corner,'-'+next);$('ground-kind').dispatchEvent(new Event('change'));}else if(tool==='cliff'){const mask=+$('cliff-mask').value;$('cliff-mask').value=((mask<<1)&15)|(mask>>3);}else if(tool==='prop'&&isScenery({kind:$('prop-kind').value}))$('scenery-rotation').value=(+$('scenery-rotation').value+90)%360;else $('rotated').checked=!$('rotated').checked;workbench?.context();lastPreview='';if(stroke||hoverPoint)preview(stroke||hoverPoint);status(note);}
 document.addEventListener('keydown',e=>{if(e.target.closest?.('input,textarea,select')||e.target.isContentEditable||document.querySelector('dialog[open]'))return;if(e.key==='Escape'){cancel();e.preventDefault();}else if(e.key.toLowerCase()==='r'&&!e.ctrlKey&&!e.metaKey){rotateBoth();e.preventDefault();}else if((e.ctrlKey||e.metaKey)&&['z','y'].includes(e.key.toLowerCase())){e.preventDefault();history(e.key.toLowerCase()==='y'||e.shiftKey?'redo':'undo');}});
 const guardReplace=()=>{if(busy||isLoading()){status('Wait for the scene update to finish.');return false;}return !hasUnsaved()||confirm('A workspace has unsaved changes. Continue replacing a design?');};
 $('new-map').onclick=async()=>{if(!guardReplace())return;recordId=null;await open(JSON.stringify(blankMap('New design')));};
 $('rename-map').onclick=async()=>{if(busy||isLoading())return;const r=getDocument().rename($('design-name').value);if(r.ok){busy=true;try{await changed();sync();}finally{busy=false;}}else status(r.error);};
 async function refreshSaves(){const selected=$('saved-designs').value,records=await listDesigns();$('saved-designs').replaceChildren(...records.sort((a,b)=>b.updated-a.updated).map(r=>new Option((JSON.parse(r.json).kind==='red-shift-block'?'Block · ':'Map · ')+r.name,r.id)));if(records.some(r=>r.id===selected))$('saved-designs').value=selected;}
 async function saveMap(copy){if(busy||isLoading())return status('Wait for the current operation to finish.');busy=true;try{const doc=getDocument(),name=$('design-name').value.trim();if(name!==doc.map.name){const r=doc.rename(name);if(!r.ok)throw Error(r.error);await changed();}const id=copy||!recordId?crypto.randomUUID():recordId,revision=doc.revision;await saveDesign({id,name:doc.map.name,json:doc.export(),updated:Date.now(),version:1});recordId=id;doc.libraryId=id;if(doc.revision===revision)doc.changed=false;await refreshSaves();$('saved-designs').value=id;sync();status('Saved in this browser. Export JSON for a portable backup.');}catch(e){status('Save failed: '+e.message);}finally{busy=false;}}
 $('save-map').onclick=()=>saveMap(false);$('save-copy').onclick=()=>saveMap(true);
 $('load-map').onclick=async()=>{if(!guardReplace())return;busy=true;try{const r=await getDesign($('saved-designs').value);if(!r)throw Error('Choose a saved design.');await open(r.json);recordId=r.id;getDocument().libraryId=r.id;}catch(e){status('Load failed: '+e.message);}finally{busy=false;}};
 const validate=()=>{const errors=getDocument().validate(),warnings=getDocument().characterWarnings(),issues=[...errors,...warnings.map(w=>'Warning: '+w)];$('validation').textContent=issues.length?issues.slice(0,8).join('\n'):getDocument().block?'Valid block - save it, then place it in a full map.':'Valid map — ready to playtest.';return errors;};
 $('validate-map').onclick=validate;$('playtest').onclick=()=>{try{if(busy||isLoading())return status('Wait for the current operation to finish.');if(getDocument().block)return status('Place the block in a full map to playtest.');if(validate().length)return;launchPlaytest(getDocument().export());status('Playtest opened. Your blueprint and undo history stay here.');}catch(e){status(e.message);}};
 function previewLight(value){scene.previewMinutes=value;const minutes=value??mapStartMinutes(getDocument()?.map);$('light-preview').value=minutes;$('light-preview-label').textContent=formatClock({minutes})+' · '+timeOfDay({minutes}).phase;scene.changed();}
 $('light-preview').oninput=()=>previewLight(+$('light-preview').value);$('light-preview-reset').onclick=()=>previewLight(null);
 function sync(){const d=getDocument();if(!d)return;$('land-height').value=Math.min(MAP_LEVELS-1,+$('floor').value);$('design-name').value=d.map.name;$('undo').disabled=!d.editor?.undo.length;$('redo').disabled=!d.editor?.redo.length;$('playtest').disabled=!!d.block;$('validation').textContent='';const start=mapStartMinutes(d.map);$('start-time').value=String(Math.floor(start/60)).padStart(2,'0')+':'+String(start%60).padStart(2,'0');$('start-time').disabled=$('apply-start-time').disabled=d.block;previewLight(scene.previewMinutes);library.sync();characterPanel.sync();tutorialPanel.sync();}
 async function run(operation,message,update=true){if(busy||isLoading())return status('Wait for the current operation to finish.');busy=true;cancel();try{await operation();if(update)await changed();sync();status(message);}catch(e){status(e.message);}finally{busy=false;}}
 $('apply-door-lock').onclick=()=>run(()=>getDocument().doorLock(getSelection(),Number($('lock-difficulty').value)),'Door lock updated.');
 $('apply-fixture-condition').onclick=()=>run(()=>getDocument().fixtureCondition(getSelection(),Number($('fixture-condition').value)),'Fixture condition updated.');
 $('add-ramp-banks').onclick=()=>run(()=>getDocument().addRampBanks(getSelection(),$('ramp-bank-surface').value),'Blocked ramp banks added.');
 $('add-lookout').onclick=()=>run(()=>getDocument().addLookout(getSelection(),options()),'Tower lookout placed.');
 $('set-helicopter-start').onclick=()=>run(()=>getDocument().crashStart(getSelection()),'Four mercs start beside the crash, facing southwest.');
 $('apply-site-sabotage').onclick=()=>run(()=>getDocument().siteSabotage(getSelection(),$('site-sabotage').checked),'Sabotage setting updated.');
 $('apply-light-mode').onclick=()=>run(()=>getDocument().lightMode(getSelection(),$('light-mode').value),'Light schedule updated.');
 $('apply-start-time').onclick=()=>run(()=>{const value=$('start-time').value;if(!/^\d{2}:\d{2}$/.test(value))throw Error('Choose a start time.');const [hours,minutes]=value.split(':').map(Number);getDocument().startTime(hours*60+minutes);},'Start time updated. Playtest starts at this time.');
 const characterPanel=installCharacterProperties({getDocument,getSelection,run,status});
 const tutorialPanel=installTutorialProperties({getDocument,getSelection,run});
 const library=installLibrary({getDocument,run,open,guardReplace,refreshSaves,status,switchWorkspace:mode=>{if(busy||isLoading()){library.sync();return;}switchWorkspace(mode).catch(e=>status(e.message));}});
 workbench=installWorkbench({rotate:rotateBoth,clearSelection:cancel,getSelection});
 refreshSaves().catch(e=>status('Browser saves unavailable: '+e.message));window.addEventListener('beforeunload',e=>{if(hasUnsaved()){e.preventDefault();e.returnValue='';}});
 return {sync,apply,run,get busy(){return busy;},get painting(){return !!stroke;},selectionChanged:()=>{characterPanel.sync();tutorialPanel.sync();if($('edit-tool').value==='inspect')$('site-sabotage').checked=getSelection()?.data?.sabotage===true;workbench?.context();},reset(){cancel();scene.previewMinutes=null;recordId=getDocument().libraryId||null;sync();workbench.floorSync();},guardReplace};
}
